import nodemailer from 'nodemailer';

let transporter = null;

export const getEmailTransporter = () => {
    const rawHost = (process.env.SMTP_HOST || '').trim();
    const user = (process.env.SMTP_USER || '').trim();
    const rawPass = (process.env.SMTP_PASS || '').trim();

    if (!user || !rawPass) {
        return null;
    }

    // Google App Passwords generated by Google have 3 spaces ("xxxx xxxx xxxx xxxx");
    // nodemailer requires the raw 16-character password without whitespace
    const pass = rawPass.replace(/\s+/g, '');

    // Determine correct SMTP host
    let host = rawHost;
    const isGmail = (
        host.toLowerCase().includes('gmail') ||
        user.toLowerCase().endsWith('@gmail.com') ||
        host.includes('@')
    );

    if (isGmail) {
        // If user put their email in SMTP_HOST, resolve to official Google SMTP service
        host = 'smtp.gmail.com';
    } else if (host.includes('@')) {
        // Provider where email was mistakenly placed in host field
        const domain = host.split('@')[1];
        host = domain ? `smtp.${domain}` : host;
    }

    const port = Number(process.env.SMTP_PORT) || 587;
    const secure = port === 465;

    try {
        if (isGmail) {
            return nodemailer.createTransport({
                service: 'gmail',
                auth: { user, pass }
            });
        }

        return nodemailer.createTransport({
            host,
            port,
            secure,
            auth: { user, pass }
        });
    } catch (err) {
        console.error('[EMAIL ERROR] Failed to create transport:', err.message);
        return null;
    }
};

/**
 * Send email helper function
 * @param {Object} options - { to, subject, text, html }
 */
export const sendEmail = async ({ to, subject, text, html }) => {
    try {
        if (!transporter) {
            transporter = getEmailTransporter();
        }

        if (!transporter) {
            console.log(`[EMAIL SIMULATION] To: ${to} | Subject: ${subject}`);
            console.log(`[EMAIL CONTENT]\n${text || html}\n----------------------------------`);
            return { success: true, simulated: true };
        }

        const rawFrom = process.env.FROM_EMAIL || process.env.SMTP_USER || 'HelpConnect <noreply@helpconnect.org>';
        const fromEmail = (rawFrom.includes('@') && !rawFrom.includes('<'))
            ? `HelpConnect <${rawFrom}>`
            : rawFrom;

        const mailOptions = {
            from: fromEmail,
            to,
            subject,
            text,
            html: html || text
        };

        const info = await transporter.sendMail(mailOptions);
        console.log(`[EMAIL SENT] MessageId: ${info.messageId} to ${to}`);
        return { success: true, info };
    } catch (error) {
        console.error('[EMAIL ERROR] Failed to send email to', to, ':', error.message);
        // Fallback simulation log so developers/testers are never locked out of verification codes
        console.log(`[EMAIL FALLBACK SIMULATION] To: ${to} | Subject: ${subject}`);
        console.log(`[EMAIL CONTENT]\n${text || html}\n----------------------------------`);
        return { success: false, error: error.message };
    }
};

export default sendEmail;
